import {isFosterStage} from './case-profile.js';
import {calcEscape as esc} from './calculator-view.js';
import {TERMS,explanationsHtml,termButton,bindTerms} from './terms.js';
export const SITUATION_OPTIONS=[
 ['planning','Planujemy narodziny dziecka','Nie jesteśmy jeszcze w ciąży, ale planujemy dziecko.'],
 ['pregnancy','Spodziewamy się narodzin dziecka','Ciąża już trwa, a dziecko jeszcze się nie urodziło.'],
 ['born','Nasze dziecko już się urodziło','Jesteśmy rodzicami dziecka, które przyszło na świat. Nie chodzi o dziecko przyjęte przez adopcję lub do pieczy zastępczej.'],
 ['adoption','Planujemy adopcję dziecka lub jesteśmy w jej trakcie','Chcemy zostać rodzicami adopcyjnymi albo rozpoczęliśmy już procedurę adopcyjną.'],
 ['adopted','Jesteśmy rodzicami adopcyjnymi','Adopcja dziecka została już prawomocnie orzeczona przez sąd.'],
 ['foster','Sprawujemy lub planujemy sprawować pieczę zastępczą','Dziecko zostało lub ma zostać umieszczone w rodzinie zastępczej albo rodzinnym domu dziecka. Nie chodzi o adopcję.'],
 ['other','Opiekuję się dzieckiem w innej sytuacji','Na przykład jestem opiekunem prawnym ustanowionym przez sąd lub członkiem rodziny sprawującym opiekę poza wymienionymi sytuacjami.']
];
export function situationCategory(p){if(p.caseStage?.startsWith('adoption-'))return 'adoption';if(isFosterStage(p.caseStage))return 'foster';if(p.caseStage==='other-care')return 'other';return ['planning','pregnancy','born','adopted'].includes(p.caseStage)?p.caseStage:'';}
export function roleQuestion(category){
 if(category==='adoption')return {name:'parentRole',title:'Czy planujesz zostać rodzicem adopcyjnym?',options:[['prospective','Tak.'],['helper','Pomagam bliskiej osobie w procesie adopcji.'],['general','Szukam ogólnych informacji.']]};
 if(category==='adopted')return {name:'parentRole',title:'Kim jesteś dla adoptowanego dziecka?',options:[['mother','Mamą.'],['father','Tatą.'],['family','Innym członkiem rodziny.']]};
 if(category==='foster')return {name:'fosterType',title:'Jaką formę pieczy zastępczej sprawujesz lub planujesz sprawować?',options:[['related-foster','Rodzina zastępcza spokrewniona.','Dziadkowie, pradziadkowie lub rodzeństwo dziecka jako formalna rodzina zastępcza.'],['foster','Rodzina zastępcza niezawodowa.','Formalna piecza pełniona niezawodowo, także przez dalszych krewnych lub osoby niespokrewnione.'],['professional','Rodzina zastępcza zawodowa.','Pełnienie funkcji zawodowo, na podstawie odpowiedniej umowy.'],['family-home','Prowadzenie rodzinnego domu dziecka.','Odrębna forma rodzinnej pieczy zastępczej; nie oznacza adopcji.'],['foster-unknown','Nie wiem / dopiero się przygotowuję.','Możesz sprawdzić formę pieczy później i korzystać z ogólnych informacji.']]};
 if(category==='other')return {name:'careStatus',title:'W jaki sposób opiekujesz się dzieckiem?',options:[['guardian','Jestem opiekunem prawnym ustanowionym przez sąd.'],['family','Jestem członkiem rodziny pomagającym w opiece.'],['other','Sprawuję inną formę opieki.'],['unknown','Nie wiem, którą odpowiedź wybrać.']]};
 return {name:'parentRole',title:'Kim jesteś dla dziecka?',options:[['mother','Mamą / przyszłą mamą.'],['father','Tatą / przyszłym tatą.'],['family','Innym członkiem rodziny.'],['unspecified','Inna sytuacja / nie chcę podawać.']]};
}
export const ADOPTION_STEPS=[['considering','Dopiero rozważamy adopcję.'],['preparing','Przygotowujemy się do adopcji.'],['procedure','Rozpoczęliśmy procedurę adopcyjną.'],['court','Wystąpiliśmy do sądu o przysposobienie dziecka.'],['placed','Dziecko zostało przyjęte na wychowanie, ale adopcja nie jest jeszcze prawomocnie zakończona.'],['unknown','Nie wiem / wolę uzupełnić później.']];
const radio=(name,options,value)=>`<div class="case-answer-list">${options.map(([id,title,description])=>`<label class="case-choice"><input type="radio" name="${name}" value="${id}" ${value===id?'checked':''}><span><strong>${title}</strong>${Object.entries(TERMS).find(([,term])=>term.match.test(title))?termButton(Object.entries(TERMS).find(([,term])=>term.match.test(title))[0]):''}${description?`<small>${description}</small>`:''}</span></label>`).join('')}</div>`;
const field=(name,title,value='',type='date')=>`<label class="calc-field"><span>${title}</span><input name="${name}" type="${type}" value="${esc(value)}" ${type==='text'?'maxlength="200"':''}></label>`;
export function caseDetailsHtml(d){
 const c=d.category,children=d.children?.length?d.children:[{name:d.name||'',birthDate:d.childBirthDate||''}],birthFields=()=>`<div id="case-children">${children.map((child,i)=>`<fieldset class="case-child"><legend>Dziecko ${i+1}</legend><div class="calc-fields">${field('childName'+i,'Imię dziecka (opcjonalnie)',child.name,'text')}${field('childBirth'+i,'Kiedy urodziło się dziecko? (opcjonalnie)',child.birthDate)}</div>${i?`<button class="text-button" type="button" data-remove-child="${i}">Usuń ten profil dziecka z formularza</button>`:''}</fieldset>`).join('')}</div><button type="button" class="secondary" id="case-add-child">Dodaj kolejne dziecko</button><p class="field-help">Każde dziecko może mieć inny wiek. Liczbę dzieci z jednego porodu lub jednoczesnego przyjęcia ustalisz osobno w kalkulatorze.</p>`;
 if(c==='planning')return `<h2>Plany na przyszłość</h2><p>Nie potrzebujemy żadnej daty.</p><fieldset><legend>Kiedy mniej więcej planujecie dziecko? (opcjonalnie)</legend>${radio('planningHorizon',[['months','W najbliższych miesiącach.'],['years','W ciągu najbliższych kilku lat.'],['unknown','Jeszcze nie wiemy.']],d.planningHorizon)}</fieldset>`;
 if(c==='pregnancy')return `<h2>Informacje o ciąży</h2><p>Możesz pominąć te informacje i uzupełnić je później.</p>${field('eventDate','Jaka jest przewidywana data porodu? (opcjonalnie)',d.eventDate||'')}${d.eventDate?'':`<details class="calc-details"><summary>Nie znam daty porodu — mogę podać tydzień ciąży</summary><p>To opcjonalna informacja orientacyjna. Nie zastępuje daty potrzebnej do konkretnego wyliczenia.</p><label class="calc-field"><span>Aktualny tydzień ciąży</span><input name="gestationWeek" type="number" min="1" max="45" step="1" value="${esc(d.gestationWeek??'')}"></label></details>`}`;
 if(c==='adoption')return `<h2>Etap adopcji</h2><fieldset><legend>Na jakim etapie adopcji jesteście?</legend>${radio('adoptionStep',ADOPTION_STEPS,d.adoptionStep||'unknown')}</fieldset><div id="adoption-dates" ${['court','placed'].includes(d.adoptionStep)?'':'hidden'}>${d.adoptionStep==='placed'?birthFields()+field('placementDate','Data przyjęcia dziecka na wychowanie (opcjonalnie)',d.placementDate||''):''}${field('adoptionApplicationDate','Data wystąpienia do sądu o przysposobienie (opcjonalnie)',d.adoptionApplicationDate||'')}</div><p class="field-help">Przed prawomocnym orzeczeniem nie traktujemy planowanej adopcji jako zakończonego przysposobienia.</p>`;
 if(c==='foster')return `<h2>Informacje o pieczy zastępczej</h2><fieldset><legend>Czy dziecko zostało już umieszczone w pieczy zastępczej?</legend>${radio('fosterPlaced',[['yes','Tak.'],['no','Nie, dopiero się przygotowujemy.'],['unknown','Nie wiem / uzupełnię później.']],d.fosterPlaced||'unknown')}</fieldset>${d.fosterPlaced==='yes'?birthFields()+field('placementDate','Data przyjęcia do pieczy zastępczej (opcjonalnie)',d.placementDate||''):''}<p class="field-help">Poszczególne formy pieczy mają różne zasady. Sama deklaracja nie potwierdza prawa do świadczenia.</p>`;
 if(c==='adopted')return `<h2>Informacje o adoptowanym dziecku</h2><p>Podaj znane informacje. Pozostałe daty będą potrzebne dopiero przy sprawdzaniu konkretnego uprawnienia.</p>${birthFields()}${field('placementDate','Data przyjęcia dziecka na wychowanie (opcjonalnie)',d.placementDate||'')}<details class="calc-details"><summary>Daty postępowania — mogę uzupełnić teraz</summary><div>${field('adoptionApplicationDate','Data wystąpienia do sądu o przysposobienie',d.adoptionApplicationDate||'')}${field('adoptionCourtDate','Data uprawomocnienia się orzeczenia o adopcji',d.adoptionCourtDate||'')}</div></details>`;
 return `<h2>${c==='born'?'Informacje o dziecku':'Informacje o dziecku, którym się opiekujesz'}</h2><p>Data urodzenia może dotyczyć dziecka w każdym wieku. Możesz ją też uzupełnić później.</p>${birthFields()}${c==='other'?'<p class="field-help">Opiekun prawny i rodzic zastępczy to różne statusy, choć niekiedy dotyczą tej samej osoby. Samo sprawowanie opieki nie ustanawia opieki prawnej.</p>':''}`;
}
export function buildCaseAnswers(d){
 const category=d.category,caseStage=category==='adoption'?(d.adoptionStep==='placed'?'adoption-placed':'adoption-pending'):category==='foster'?(d.fosterType||'foster-unknown'):category==='other'?'other-care':category||'planning';
 const relevantChildren=['born','adopted','other'].includes(category)||(category==='adoption'&&d.adoptionStep==='placed')||(category==='foster'&&d.fosterPlaced==='yes');
 const children=relevantChildren?d.children||[]:[],placementRelevant=category==='adopted'||category==='adoption'&&d.adoptionStep==='placed'||category==='foster'&&d.fosterPlaced==='yes';
 return {completedTasks:d.completedTasks||[],notApplicableTasks:d.notApplicableTasks||[],dates:d.dates||{},formal:true,onboardingComplete:true,life:d.life===true,schoolDelayed:d.schoolDelayed===true,activeChildId:d.activeChildId||'',situationId:d.situationId,caseStage,parentRole:category==='foster'?'caregiver':category==='other'?(d.careStatus==='family'?'family':'caregiver'):d.parentRole||'unspecified',careStatus:category==='other'?d.careStatus||'unknown':'unknown',adoptionStep:category==='adoption'?d.adoptionStep||'unknown':'unknown',fosterPlaced:category==='foster'?d.fosterPlaced||'unknown':'unknown',children,name:children[0]?.name||'',childBirthDate:children[0]?.birthDate||'',eventDate:category==='pregnancy'?d.eventDate||'':'',dueDate:category==='pregnancy'?d.eventDate||'':null,placementDate:placementRelevant?d.placementDate||'':'',adoptionApplicationDate:category==='adopted'||category==='adoption'&&['court','placed'].includes(d.adoptionStep)?d.adoptionApplicationDate||'':'',adoptionCourtDate:category==='adopted'?d.adoptionCourtDate||'':'',planningHorizon:category==='planning'?d.planningHorizon||'unknown':'unknown',gestationWeek:category==='pregnancy'&&!d.eventDate?d.gestationWeek||'':null,gestationObservedDate:d.gestationObservedDate||'',guideOnly:d.guideOnly===true};
}
export function caseOnboardingHtml(brand,profile={},edit=false){return `<main class="case-onboarding ${edit?'case-editor':''}">${brand}<div class="case-start-layout"><section class="case-start-intro"><span class="eyebrow">Przewodnik Przyszłego Rodzica</span><h1>Wasza sytuacja.<br>Wasze uprawnienia.</h1><p>Świadczenia, urlopy i formalności — z myślą o Waszej rodzinie.</p><div class="case-start-benefits"><p>Zacznij bez logowania i bez danych o zarobkach.</p><p>Nieznane daty możesz uzupełnić później.</p><p>Inne dzieci i kolejne sytuacje dodasz w profilu.</p></div><img src="assets/onboarding-baby.png" alt="" width="150" height="150"></section><section class="case-start-panel"><nav class="case-progress" aria-label="Pytania początkowe"><span>Sytuacja</span><span>Twoja rola</span><span>Znane informacje</span></nav><form id="case-profile-form" novalidate></form></section></div></main>`;}
export function bindCaseProfileForm(root,onSave,{profile={},edit=false,onCancel,onSpecial,startStep=0}={}){
 const form=root.querySelector('#case-profile-form');let step=startStep;let d={...profile,category:situationCategory(profile),fosterType:isFosterStage(profile.caseStage)?profile.caseStage:'',children:structuredClone(profile.children||[])};
 bindTerms(root);
 const capture=()=>{const data=new FormData(form);for(const key of ['parentRole','fosterType','careStatus','planningHorizon','eventDate','gestationWeek','placementDate','adoptionApplicationDate','adoptionCourtDate'])if(data.has(key))d[key]=data.get(key);const childInputs=[...form.querySelectorAll('[name^=childName]')];if(childInputs.length)d.children=childInputs.map((el,i)=>({id:d.children[i]?.id||'child-'+i,name:el.value,birthDate:form.elements['childBirth'+i].value}));};
 const draw=()=>{
 const question=roleQuestion(d.category),ids=step===0?['adoption','foster','guardian']:step===1?d.category==='foster'?['foster','related','nonprofessional','professional','home']:d.category==='other'?['guardian','family']:d.category.startsWith('adop')?['adoption','adoptive','family']:['family']:d.category.startsWith('adop')?['adoption','adoptive']:d.category==='foster'?['foster','guardian']:d.category==='other'?['guardian','family']:[];
 form.innerHTML=`<p class="eyebrow">${edit?'Aktualizacja profilu':'Poznajmy Waszą sytuację'} · ${step+1} z 3</p>${step===0?`<h2>W jakiej sytuacji jesteś?</h2><p>Wybierz odpowiedź, która najlepiej opisuje Twoją sytuację. Dzięki temu pokażemy Ci odpowiednie informacje o urlopach, świadczeniach i formalnościach.</p><fieldset id="case-stage"><legend class="sr-only">Twoja sytuacja</legend>${radio('category',SITUATION_OPTIONS,d.category)}</fieldset><p class="field-help">Wybierz jedną sytuację na początek. Kolejne dodasz w profilu.</p>`:step===1?`<h2>${question.title}</h2><fieldset id="case-role"><legend class="sr-only">Twoja rola lub forma opieki</legend>${radio(question.name,question.options,d[question.name])}</fieldset><p class="field-help">Ta odpowiedź dopasowuje przewodnik. Sama rola lub forma opieki nie potwierdza prawa do urlopu ani świadczenia.</p>`:caseDetailsHtml(d)}${ids.length?explanationsHtml(ids):''}<p id="case-profile-error" class="calc-error" role="alert" hidden></p><div class="case-wizard-actions">${step?'<button type="button" class="secondary" id="case-back">Wstecz</button>':''}<button class="primary" type="submit">${step<2?'Dalej':edit?'Zapisz informacje':'Otwórz przewodnik'}</button></div><div class="case-quiet-actions"><button class="text-button" type="button" id="case-skip">${step===2?'Pomiń nieznane informacje':'Przeglądaj bez uzupełniania profilu'}</button>${onCancel?'<button class="text-button" type="button" id="case-cancel">Anuluj zmiany</button>':''}<button class="text-button" type="button" id="case-special">Potrzebuję wsparcia w szczególnej sytuacji</button></div>`;
 root.querySelectorAll('.case-progress span').forEach((el,i)=>{el.classList.toggle('active',i===step);if(i===step)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});
 form.querySelector('#case-back')?.addEventListener('click',()=>{capture();step--;draw();});
 form.querySelector('#case-skip').onclick=()=>{capture();if(step===2){save();}else{try{onSave(buildCaseAnswers({category:'planning',parentRole:'unspecified',guideOnly:true,situationId:d.situationId}));}catch(e){showError(e);}}};
 form.querySelector('#case-cancel')?.addEventListener('click',onCancel);form.querySelector('#case-special').onclick=()=>onSpecial?.();
 form.querySelector('#case-add-child')?.addEventListener('click',()=>{capture();if(!d.children.length)d.children=[{name:d.name||'',birthDate:d.childBirthDate||''}];if(d.children.length>=20){showError(new Error('Możesz dodać do 20 dzieci w tej sytuacji.'));return;}d.children.push({id:'child-'+Date.now(),name:'',birthDate:''});draw();});
 form.querySelectorAll('[data-remove-child]').forEach(b=>b.onclick=()=>{capture();d.children.splice(Number(b.dataset.removeChild),1);draw();});
 form.onchange=e=>{if(e.target.name==='category'){capture();const next=e.target.value;if(next!==d.category){d={...d,...buildCaseAnswers({category:next,situationId:d.situationId}),category:next,parentRole:'',fosterType:'',careStatus:'',children:[],adoptionStep:'unknown',fosterPlaced:'unknown',life:false,schoolDelayed:false};}draw();}else if(['adoptionStep','fosterPlaced','eventDate'].includes(e.target.name)){capture();d[e.target.name]=e.target.value;draw();}else form.querySelector('#case-profile-error').hidden=true;};
 form.onsubmit=e=>{e.preventDefault();capture();if(step===0&&!d.category)return showError(new Error('Wybierz sytuację albo skorzystaj z przewodnika bez uzupełniania profilu.'));if(step===1&&!d[question.name])return showError(new Error('Wybierz odpowiedź pasującą do Twojej roli. Możesz też wybrać „Nie wiem” lub przejść do ogólnych informacji.'));if(step<2){step++;draw();form.querySelector('h2')?.scrollIntoView({block:'nearest'});}else save();};
 };
 function showError(error){const el=form.querySelector('#case-profile-error');el.hidden=false;el.innerHTML='<svg class="blue-alert" viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M12 3 2 21h20Z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M12 9v5m0 3v1" stroke="currentColor" stroke-width="2"/></svg> '+esc(error.message);form.querySelector('fieldset')?.setAttribute('aria-invalid','true');el.scrollIntoView({block:'nearest'});}
 function save(){try{onSave(buildCaseAnswers(d));}catch(error){showError(error);}}
 draw();
}
